"""ROT-n: shift ASCII letters by n places, wrapping around the alphabet."""


def rot(text, n):
    """Shift each ASCII letter in text by n places, keeping case. Other characters are unchanged.

    n must be an int (bool is rejected); any integer is allowed, including negative values.
    """
    if isinstance(n, bool) or not isinstance(n, int):
        raise ValueError(f"n must be an integer, not {type(n).__name__}")
    shift = n % 26
    out = []
    for ch in text:
        if "a" <= ch <= "z":
            out.append(chr((ord(ch) - ord("a") + shift) % 26 + ord("a")))
        elif "A" <= ch <= "Z":
            out.append(chr((ord(ch) - ord("A") + shift) % 26 + ord("A")))
        else:
            out.append(ch)
    return "".join(out)
"""slug: turn text into a lower-case, separator-joined ASCII slug, e.g. for URLs."""
import re
import unicodedata

_RUN = re.compile(r"[a-z0-9]+")


def slugify(text, sep="-"):
    """Return text as a slug: ASCII a-z and 0-9 words joined by sep.

    Accents are folded with NFKD and the rest of the non-ASCII characters are dropped.
    Every other run of characters becomes a single sep, with none at the ends.
    Raises ValueError if nothing is left.
    """
    folded = unicodedata.normalize("NFKD", text).encode("ascii", "ignore").decode("ascii")
    words = _RUN.findall(folded.lower())
    if not words:
        raise ValueError(f"nothing left to slugify in {text!r}")
    return sep.join(words)
import contextlib
import io
import sys
import unittest
from unittest import mock

from textkit.cli import main
from textkit.rot import rot


def run(argv, stdin=""):
    out, err = io.StringIO(), io.StringIO()
    with mock.patch.object(sys, "stdin", io.StringIO(stdin)), \
            contextlib.redirect_stdout(out), contextlib.redirect_stderr(err):
        code = main(argv)
    return code, out.getvalue(), err.getvalue()


class RotFunctionTest(unittest.TestCase):
    def test_default_example(self):
        self.assertEqual(rot("Hello, World!", 13), "Uryyb, Jbeyq!")

    def test_wraps_around_and_keeps_case(self):
        self.assertEqual(rot("xyzXYZ", 3), "abcABC")

    def test_leaves_other_characters(self):
        self.assertEqual(rot("1 2-3_!? \n\t", 5), "1 2-3_!? \n\t")

    def test_negative_shift(self):
        self.assertEqual(rot("abc", -1), "zab")

    def test_large_and_negative_shifts_wrap(self):
        self.assertEqual(rot("abc", 27), "bcd")
        self.assertEqual(rot("abc", -53), "zab")

    def test_zero_is_identity(self):
        self.assertEqual(rot("Keep Me", 0), "Keep Me")

    def test_rot13_is_its_own_inverse(self):
        self.assertEqual(rot(rot("Round Trip", 13), 13), "Round Trip")

    def test_non_ascii_letters_unchanged(self):
        self.assertEqual(rot("café", 1), "dbgé")

    def test_rejects_float(self):
        with self.assertRaises(ValueError):
            rot("abc", 1.5)

    def test_rejects_string(self):
        with self.assertRaises(ValueError):
            rot("abc", "1")

    def test_rejects_bool(self):
        with self.assertRaises(ValueError):
            rot("abc", True)
        with self.assertRaises(ValueError):
            rot("abc", False)


class RotCommandTest(unittest.TestCase):
    def test_default_shift_is_13(self):
        code, out, err = run(["rot", "Hello, World!"])
        self.assertEqual((code, out, err), (0, "Uryyb, Jbeyq!\n", ""))

    def test_negative_n(self):
        code, out, _ = run(["rot", "abc", "--n", "-1"])
        self.assertEqual((code, out), (0, "zab\n"))

    def test_large_n(self):
        code, out, _ = run(["rot", "abc", "--n", "27"])
        self.assertEqual((code, out), (0, "bcd\n"))

    def test_float_n_is_an_error(self):
        code, out, err = run(["rot", "abc", "--n", "1.5"])
        self.assertEqual(code, 2)
        self.assertEqual(out, "")
        self.assertTrue(err.startswith("error: "), err)

    def test_non_numeric_n_is_an_error(self):
        code, out, err = run(["rot", "abc", "--n", "x"])
        self.assertEqual(code, 2)
        self.assertEqual(out, "")
        self.assertTrue(err.startswith("error: "), err)

    def test_json_output(self):
        code, out, _ = run(["--json", "rot", "abc", "--n", "1"])
        self.assertEqual(code, 0)
        self.assertEqual(out, '{"command": "rot", "exit": 0, "output": ["bcd"]}\n')

    def test_listed_in_commands(self):
        _, out, _ = run(["commands"])
        self.assertIn("rot\n", out)


if __name__ == "__main__":
    unittest.main()
