"""wrap: fill text to a line width, greedily, keeping paragraphs apart."""


def _paragraphs(text):
    """Yield each paragraph as a list of words. Blank lines (empty or whitespace-only) separate them."""
    words = []
    for line in text.splitlines():
        if line.strip():
            words.extend(line.split())
        elif words:
            yield words
            words = []
    if words:
        yield words


def _fill(words, width):
    """Greedily pack words into lines of at most width characters. A longer word gets a line of its own."""
    lines = []
    line = ""
    for word in words:
        if not line:
            line = word
        elif len(line) + 1 + len(word) <= width:
            line += " " + word
        else:
            lines.append(line)
            line = word
    lines.append(line)
    return lines


def wrap(text, width):
    """Return text wrapped to width characters, joined with "\\n" and with no trailing newline.

    Whitespace inside a paragraph collapses to single spaces. Paragraphs are separated by exactly
    one empty line. Words are never split, so a word longer than width sits alone on its line.
    Raises ValueError if width < 1.
    """
    if width < 1:
        raise ValueError(f"width must be at least 1, not {width}")
    return "\n\n".join("\n".join(_fill(words, width)) for words in _paragraphs(text))

