import contextlib
import io
import sys
import unittest
from unittest import mock

from textkit.cli import main
from textkit.wrap import wrap


def run(argv):
    out, err = io.StringIO(), io.StringIO()
    with contextlib.redirect_stdout(out), contextlib.redirect_stderr(err):
        code = main(argv)
    return code, out.getvalue(), err.getvalue()


class WrapFunctionTest(unittest.TestCase):
    def test_fills_greedily(self):
        self.assertEqual(wrap("aaa bbb ccc", 7), "aaa bbb\nccc")
        self.assertEqual(wrap("aaa bbb ccc", 11), "aaa bbb ccc")
        self.assertEqual(wrap("aaa bbb ccc", 3), "aaa\nbbb\nccc")

    def test_collapses_whitespace_and_newlines_inside_paragraph(self):
        self.assertEqual(wrap("one\ttwo\n  three   four", 40), "one two three four")

    def test_paragraphs_separated_by_exactly_one_empty_line(self):
        self.assertEqual(wrap("first para\n\n\n\nsecond para", 40), "first para\n\nsecond para")

    def test_blank_lines_with_whitespace_separate_paragraphs(self):
        self.assertEqual(wrap("a b\n   \t\nc d", 40), "a b\n\nc d")

    def test_no_leading_or_trailing_blank_lines(self):
        self.assertEqual(wrap("\n\n  hello\n\n", 40), "hello")

    def test_empty_and_blank_text(self):
        self.assertEqual(wrap("", 10), "")
        self.assertEqual(wrap(" \n \n\t", 10), "")

    def test_long_word_goes_on_its_own_line_unbroken(self):
        self.assertEqual(wrap("hi supercalifragilistic yo", 5), "hi\nsupercalifragilistic\nyo")

    def test_long_word_first(self):
        self.assertEqual(wrap("abcdefgh x", 3), "abcdefgh\nx")

    def test_hyphenated_word_is_not_split(self):
        self.assertEqual(wrap("well-known fact here", 9), "well-known\nfact here")

    def test_width_one_puts_each_word_on_a_line(self):
        self.assertEqual(wrap("a bb c", 1), "a\nbb\nc")

    def test_exact_width_fits(self):
        self.assertEqual(wrap("abcd efgh", 9), "abcd efgh")

    def test_rejects_width_below_one(self):
        with self.assertRaises(ValueError):
            wrap("abc", 0)
        with self.assertRaises(ValueError):
            wrap("abc", -3)

    def test_no_trailing_newline(self):
        self.assertFalse(wrap("a\n\nb c", 40).endswith("\n"))


class WrapCommandTest(unittest.TestCase):
    def test_prints_wrapped_text(self):
        code, out, err = run(["wrap", "aaa bbb ccc", "--width", "7"])
        self.assertEqual((code, out, err), (0, "aaa bbb\nccc\n", ""))

    def test_default_width_is_40(self):
        text = "word " * 12
        code, out, _ = run(["wrap", text.strip()])
        self.assertEqual(code, 0)
        self.assertEqual(out, wrap(text.strip(), 40) + "\n")
        self.assertTrue(all(len(line) <= 40 for line in out.splitlines()))

    def test_width_zero_is_an_error(self):
        code, out, err = run(["wrap", "x", "--width", "0"])
        self.assertEqual(code, 2)
        self.assertEqual(out, "")
        self.assertTrue(err.startswith("error: "), err)

    def test_non_integer_width_is_an_error(self):
        with mock.patch.object(sys, "stderr", io.StringIO()), self.assertRaises(SystemExit) as cm:
            run(["wrap", "x", "--width", "wide"])
        self.assertEqual(cm.exception.code, 2)

    def test_json_output(self):
        code, out, _ = run(["--json", "wrap", "aaa bbb ccc", "--width", "7"])
        self.assertEqual(code, 0)
        self.assertEqual(out, '{"command": "wrap", "exit": 0, "output": ["aaa bbb", "ccc"]}\n')

    def test_listed_in_commands(self):
        _, out, _ = run(["commands"])
        self.assertIn("wrap\n", out)


if __name__ == "__main__":
    unittest.main()

